src/interfaces/ICOURCurve.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { TokenConfig } from "../types/TokenConfig.sol";

/// @title ICOURCurve
/// @notice Virtual constant-product bonding curve (one EIP-1167 clone per token), priced in stock.
interface ICOURCurve {
    /// @notice Initialize the clone. Only the factory, once.
    function initialize(TokenConfig calldata cfg) external;

    /// @notice Tax-free (fee still applies) creator initial buy performed atomically in createToken.
    ///         Only the factory. Stock is pulled from the factory.
    function initialBuy(uint256 stockIn, uint256 minTokensOut, address to)
        external
        returns (uint256 tokensOut, uint256 stockUsed);

    /// @notice Buy tokens with `stockIn` gross stock (fee + launch tax applied inside).
    /// @return tokensOut tokens delivered to `to`.
    /// @return stockUsed gross stock actually consumed (may be < stockIn if the buy graduates with a refund).
    function buy(uint256 stockIn, uint256 minTokensOut, address to, uint256 deadline)
        external
        returns (uint256 tokensOut, uint256 stockUsed);

    /// @notice Sell `tokensIn` tokens for stock (fee applied inside, no launch tax).
    function sell(uint256 tokensIn, uint256 minStockOut, address to, uint256 deadline)
        external
        returns (uint256 stockOut);

    // --- quotes (views) ---
    function quoteBuy(uint256 stockIn) external view returns (uint256 tokensOut, uint256 fee, uint256 tax);
    function quoteSell(uint256 tokensIn) external view returns (uint256 stockOut, uint256 fee);
    function quoteStockForTokens(uint256 tokensWanted) external view returns (uint256 stockIn);

    /// @notice Progress toward graduation in bps (sold / soldAtStop).
    function progressBps() external view returns (uint256);

    function graduated() external view returns (bool);
    function vS() external view returns (uint256);
    function vT() external view returns (uint256);
    function config() external view returns (TokenConfig memory);
}

src/interfaces/ICOURFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { TokenConfig } from "../types/TokenConfig.sol";
import { ICOURPriceReader } from "./ICOURPriceReader.sol";

/// @title ICOURFactory
/// @notice Launches COUR tokens and graduates them into Uniswap v4 pools with the COUR hook.
interface ICOURFactory {
    struct CreateParams {
        string name;
        string symbol;
        string metadataURI;
        address stock; // must be allowlisted
        uint16 creatorFeeBps; // 100..1000
        uint8 creatorMode; // 0..3
        address feeRecipient; // creator-side recipient; defaults to msg.sender if zero
        uint256 initialBuyStock; // optional tax-free launch buy; capped at 50% supply
        uint256 minInitialTokens; // slippage bound for the initial buy
        bytes32 salt; // CREATE2 salt for a deterministic token address
    }

    function createToken(CreateParams calldata p) external payable returns (address token, address curve);

    /// @notice Build the graduation pool, add full-range liquidity, burn the position. Only the token's curve.
    function graduate(address token) external;

    // --- views used by curve / hook / vault ---
    function tokenConfig(address token) external view returns (TokenConfig memory);
    function curveOf(address token) external view returns (address);
    function isCOURToken(address token) external view returns (bool);
    function poolIdOf(address token) external view returns (bytes32);
    function hook() external view returns (address);
    function feeVault() external view returns (address);
    function priceReader() external view returns (ICOURPriceReader);
    function poolManager() external view returns (address);

    // --- admin ---
    function setStock(address stock, bool allowed, address refPool, ICOURPriceReader.RefKind kind) external;
    function setLaunchParams(uint256 startMcUsd, uint256 gradMcUsd, uint256 minRefLiqUsd, uint256 launchFee) external;
    function setLaunchesPaused(bool paused) external;
    function stockAllowed(address stock) external view returns (bool);

    /// @notice Gate NEW launches to an allowlist of creators (existing tokens are unaffected).
    function setLaunchAllowlist(address account, bool allowed) external;
    function setLaunchAllowlistEnabled(bool enabled) external;
    function launchAllowlistEnabled() external view returns (bool);
    function launchAllowlist(address account) external view returns (bool);
}

src/interfaces/ICOURFeeVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { CreatorMode } from "../types/CreatorMode.sol";

/// @title ICOURFeeVault
/// @notice Holds and routes the creator fee (taken in the stock token) per the 80/20 split and the
///         per-token creator mode. Resilient to a paused stock token: claims revert, accounting never corrupts.
interface ICOURFeeVault {
    /// @notice Register a token's fee config. Called once by the factory at launch.
    function registerToken(
        address token,
        address stock,
        address creator,
        uint16 creatorFeeBps,
        CreatorMode mode,
        address feeRecipient
    ) external;

    /// @notice Notify the vault that `amount` of stock fee arrived for `token`. Only hook or curve.
    /// @dev The stock is assumed already transferred to the vault by the caller (hook `take`, curve transfer).
    function notify(address token, uint256 amount) external;

    /// @notice CREATOR mode: creator claims the accrued creator-side fees.
    function claim(address token) external returns (uint256 amount);

    /// @notice HOLDERS mode: caller claims their pro-rata dividend.
    function claimHolder(address token) external returns (uint256 amount);

    /// @notice Hook on token balance changes (HOLDERS mode only). Only the token may call.
    function beforeBalanceChange(address from, address to, uint256 amount) external;

    /// @notice BUYBACK / BUYBACK_BURN: creator spends accrued buyback funds buying the token.
    function executeBuyback(address token, uint256 maxStockIn, uint256 minTokensOut)
        external
        returns (uint256 stockIn, uint256 tokensOut);

    /// @notice Send accrued platform fees for a stock to the treasury. Anyone may call.
    function claimPlatform(address stock) external returns (uint256 amount);

    /// @notice Credit already-transferred stock to the platform bucket (graduation dust). Only the factory.
    function creditPlatform(address stock, uint256 amount) external;

    /// @notice Two-step creator-recipient transfer.
    function setFeeRecipient(address token, address newRecipient) external;
    function acceptFeeRecipient(address token) external;

    // --- views ---
    function creatorOwed(address token) external view returns (uint256);
    function buybackOwed(address token) external view returns (uint256);
    function platformOwed(address stock) external view returns (uint256);
    function pendingHolder(address token, address holder) external view returns (uint256);
    function feeRecipient(address token) external view returns (address);
    function treasury() external view returns (address);
}

src/interfaces/ICOURHook.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ICOURHook
/// @notice COUR Uniswap v4 hook: captures the creator fee on pool swaps (in stock) and maintains a
///         per-pool tick accumulator providing a short-window TWAP for the buyback guard.
interface ICOURHook {
    /// @notice Time-weighted arithmetic-mean tick for `poolId` over the last `secondsAgo` seconds.
    function consult(bytes32 poolId, uint32 secondsAgo) external view returns (int24 arithmeticMeanTick);

    /// @notice Pool spot price (stock per token, 1e18) and TWAP price for the buyback deviation guard.
    function priceInfo(address token) external view returns (uint256 spotX18, uint256 twapX18);

    /// @notice Best-effort stock-side reserve of the graduated full-range pool (for the 2% buyback cap).
    function poolStockReserve(address token, address stock) external view returns (uint256);

    /// @notice True once the observed TWAP window spans at least HOOK_TWAP_WINDOW seconds, i.e. the TWAP
    ///         used by the buyback deviation guard is backed by a full window of observations (L-2).
    function twapWindowFull(address token) external view returns (bool);
}

